export class AiProgrammerApp extends App {
	private elementBuilder: ElementBuilder;
    private blockBuilder: BlockBuilder;
	constructor(info: IAppInfo, logger: ILogger, accessors: IAppAccessors) {
		super(info, logger, accessors);
	}


	public async extendConfiguration(configuration: IConfigurationExtend) {
		await Promise.all([
			...settings.map((setting) =>
				configuration.settings.provideSetting(setting)
			),
			configuration.slashCommands.provideSlashCommand(
				new CodeCommand(this)
			),
		]);
		this.elementBuilder = new ElementBuilder(this.getID());
        this.blockBuilder = new BlockBuilder(this.getID());
	}

	public getUtils(){
        return {
            elementBuilder: this.elementBuilder,
            blockBuilder: this.blockBuilder,
        };
    }

	public async executeBlockActionHandler(
        context: UIKitBlockInteractionContext,
        read: IRead,
        http: IHttp,
        persistence: IPersistence,
        modify: IModify
    ): Promise<IUIKitResponse> {
        const handler = new ExecuteBlockActionHandler(
            this,
            read,
            http,
            persistence,
            modify,
            context
        );

        return await handler.handleActions();
    }

    public async executeViewSubmitHandler(
        context: UIKitViewSubmitInteractionContext,
        read: IRead,
        http: IHttp,
        persistence: IPersistence,
        modify: IModify
    ): Promise<IUIKitResponse> {
        const handler = new ExecuteViewSubmitHandler(
            this,
            read,
            http,
            persistence,
            modify,
            context
        );

        return await handler.handleActions();
    }

    public async executeViewClosedHandler(
        context: UIKitViewCloseInteractionContext,
        read: IRead,
        http: IHttp,
        persistence: IPersistence,
        modify: IModify
    ): Promise<IUIKitResponse> {
        const handler = new ExecuteViewClosedHandler(
            this,
            read,
            http,
            persistence,
            modify,
            context
        );

        return await handler.handleActions();
    }

	public async executeActionButtonHandler(
        context: UIKitActionButtonInteractionContext,
        read: IRead,
        http: IHttp,
        persistence: IPersistence,
        modify: IModify
    ): Promise<IUIKitResponse> {
        const handler = new ExecuteActionButtonHandler(
            this,
            read,
            http,
            persistence,
            modify,
            context
        );

        return await handler.handleActions();
    }
}

import { IRead } from '@rocket.chat/apps-engine/definition/accessors';
import { IRoom } from '@rocket.chat/apps-engine/definition/rooms';
import { IUser } from '@rocket.chat/apps-engine/definition/users';

export async function notifyMessage(
	room: IRoom,
	read: IRead,
	user: IUser,
	message: string,
	threadId?: string
): Promise<void> {
	const notifier = read.getNotifier();

	const messageBuilder = notifier.getMessageBuilder();
	messageBuilder.setText(message);
	messageBuilder.setRoom(room);

	if (threadId) {
		messageBuilder.setThreadId(threadId);
	}

	return notifier.notifyUser(user, messageBuilder.getMessage());
}

import { IRead, IPersistence, IHttp, IModify } from '@rocket.chat/apps-engine/definition/accessors';
import { IRoom } from '@rocket.chat/apps-engine/definition/rooms';
import { IUser } from '@rocket.chat/apps-engine/definition/users';
import { SlashCommandContext } from "@rocket.chat/apps-engine/definition/slashcommands";
import { notifyMessage } from './notifyMessage';
import { sendNotification } from "./message";
import { App } from '@rocket.chat/apps-engine/definition/App';

export async function generateCode(
	app: App,
	room: IRoom,
	read: IRead,
	user: IUser,
	http: IHttp,
    persistence: IPersistence,
    modify: IModify,
    language: string,
    LLM: string,
	prompt: string
): Promise<string> {
	const model = await app
		.getAccessors()
		.environmentReader.getSettings()
		.getValueById('model');
	const url = `http://${LLM}/v1`;

	const body = {
		model,
		messages: [
			{
				role: 'system',
				content: prompt,
			},
		],
		temperature: 0,
	};

	const response = await http.post(url + '/chat/completions', {
		headers: {
			'Content-Type': 'application/json',
		},
		content: JSON.stringify(body),
	});

	if (!response.content) {
		await sendNotification(
			read,
			modify,
			user,
			room,
			"Something is wrong with AI. Please try again later! "
        );
		throw new Error('Something is wrong with AI. Please try again later');
	}

	return JSON.parse(response.content).choices[0].message.content;
}

